import json, subprocess, sys
MAIN='/workspace/submission/main.py'
def comp(cfg_bytes):
    p=subprocess.run([sys.executable,'-I',MAIN,'compile'],input=cfg_bytes,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
    return p.returncode,p.stdout
valid={"version":1,"idle_timeout":0,"packet_limit":1,"prefix_width":1,"rules":[],"fallback":{"class":0}}
# complete binary tree depth 8 -> 511 nodes
def full(d):
    if d==0: return {"class":0}
    return {"feature":0,"threshold":0,"le":full(d-1),"gt":full(d-1)}
c=dict(valid); c["fallback"]=full(8)
rc,out=comp(json.dumps(c).encode()); print("nodes511",rc,out[:40])
# depth 16 exactly allowed: chain of 16 edges = 17 nodes
node={"class":0}
for _ in range(16): node={"feature":0,"threshold":0,"le":node,"gt":node}
c=dict(valid); c["fallback"]=node
rc,out=comp(json.dumps(c).encode()); print("depth16 chain (shared) -> nodes count =17",rc,out[:40])
big={"version":1,"idle_timeout":10**9,"packet_limit":10**9,"prefix_width":32,"rules":[{"id":i,"class":65535,"priority":2**31-1,"ranges":[[-2048,2048]]} for i in range(2048)],"fallback":{"class":0}}
rc,out=comp(json.dumps(big).encode()); print("big valid",rc,len(out), out[:30])
# total positions 16384: 512 rules * 32
rules=[{"id":i,"class":0,"priority":0,"ranges":[[1,1]]*32} for i in range(512)]
c=dict(valid); c["rules"]=rules
rc,out=comp(json.dumps(c).encode()); print("16384 positions",rc,len(out))
